const results = await Promise.allSettled([
  tools.exec_command({cmd:"\"$STAMPED_ASSESSMENT_PYTHON\" \"$STAMPED_ASSESSMENT_RUNNER\" check",yield_time_ms:30000,max_output_tokens:4000}),
  tools.exec_command({cmd:"cat \"$STAMPED_ASSESSMENT_VERSION\" && cat \"$STAMPED_DELIVERY_MANIFEST\" && cat \"$STAMPED_OPERATIONAL_MANIFEST\" && cat \"$STAMPED_PROCEDURE\"",yield_time_ms:10000,max_output_tokens:8000}),
  tools.exec_command({cmd:"rg --files -g 'judge-target.json' -g '*guidance*' -g 'worker-end-state.json' ..",yield_time_ms:10000,max_output_tokens:3000})
]);
for (let i=0;i<results.length;i++) { const r=results[i]; text(`TASK ${i+1}\n${r.status==="fulfilled" ? r.value.output : String(r.reason)}`); }

