 h=Path(base)
 for n in list(dirs):
  p=h/n; rel=p.relative_to(root).as_posix(); st=p.lstat()
  if stat.S_ISLNK(st.st_mode):
   t=os.readlink(p); current[rel]={'kind':'symlink','mode':stat.S_IMODE(st.st_mode),'target':t,'sha256':hashlib.sha256(os.fsencode(t)).hexdigest()};dirs.remove(n)
  else: current[rel]={'kind':'directory','mode':stat.S_IMODE(st.st_mode)}
 for n in files:
  p=h/n;rel=p.relative_to(root).as_posix();st=p.lstat()
  if stat.S_ISLNK(st.st_mode):
   t=os.readlink(p);current[rel]={'kind':'symlink','mode':stat.S_IMODE(st.st_mode),'target':t,'sha256':hashlib.sha256(os.fsencode(t)).hexdigest()}
  elif stat.S_ISREG(st.st_mode):
   hsh=hashlib.sha256()
   with p.open('rb') as f:
    for b in iter(lambda:f.read(1<<20),b''):hsh.update(b)
   current[rel]={'kind':'file','mode':stat.S_IMODE(st.st_mode),'size':st.st_size,'sha256':hsh.hexdigest()}
  else:current[rel]={'kind':'other','mode':stat.S_IMODE(st.st_mode)}
missing=sorted(set(initial)-set(current));added=sorted(set(current)-set(initial));changed=[]
for rel in sorted(set(initial)&set(current)):
 old=initial[rel];now=current[rel]
 if any(old.get(f)!=now.get(f) for f in ('kind','mode','size','sha256')):
  changed.append({'path':rel,'initial_sha256':old.get('sha256'),'current_sha256':now.get('sha256'),'initial_kind':old.get('kind'),'current_kind':now.get('kind')})
allowed={'.git/annex/keysdb/db','.git/annex/keysdb/db-shm','.git/annex/keysdb/db-wal'}
